/**
 * @method
 * @name scwin.fnShowKosdaqSeg
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.fnShowKosdaqSeg = function (obj) {
    /* sdd-asis-lifecycle:begin fnShowKosdaqSeg — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (obj.val() === "kosdaqMkt") {
        scwin.kosdaqSeg.setStyle("display", "");
    } else {
        scwin.kosdaqSeg.setStyle("display", "none");
    }
    $("#searchForm").find("input:radio[name=rd_kosdaqSegment]:input#rSeg").prop("checked", true);
    scwin.fnTooltip();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnTooltip
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnTooltip = function () {
    /* sdd-asis-lifecycle:begin fnTooltip — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $(".tttt").hover(function(e) {
            const varTop = $(this).position().top;
            const varLeft = $(this).position().left;
            $("#qmark").css("top", varTop - 10);
            $("#qmark").css("left", varLeft + 15);
            document.qmark.setStyle("display", "");
        }, function(e) {
            document.qmark.setStyle("display", "none");
    });
    /* sdd-asis-lifecycle:end */
};
